package main
import "fmt"

//定义 route() 函数

func route(cities ...string) {

    var result string
    for _, v := range cities {
        result += v + "->"
    }
    fmt.Println(result)
}

func main() {
    var n int
    fmt.Scanln(&n)

    var cities []string
    //输入n个字符串，并存储在切片cities中
  
    var tmp string
    for i:=0; i<n; i++ {
        fmt.Scanln(&tmp)
        cities = append(cities, tmp)
    }
    // 调用route函数
    route(cities...)
}
